test('vatSummary returns entries for each VAT rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const report = vatSummary([r2.value]);

  assert.equal(report.length, 1);
  assert.equal(report[0].rate, 0.21);
  assert.equal(report[0].base, 10 * 9500);
  assert.equal(report[0].vat, Math.round(10 * 9500 * 0.21));
});

test('vatSummary sorts by rate descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PREMIUM-HOUR', qty: 5, discountPercent: 0 },
    ],
  });
  const r2 = issueInvoice(r1.value, []);

  const report = vatSummary([r2.value]);

  if (report.length > 1) {
    for (let i = 0; i < report.length - 1; i++) {
      assert(report[i].rate >= report[i + 1].rate);
    }
  }
});

test('vatSummary groups multiple invoices by VAT rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const r4 = issueInvoice(r3.value, ['INV-2026-0001']);

