import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Get overdue invoices report.
 * @param {Array} invoices - Array of invoice objects
 * @param {string} asOf - Report date in YYYY-MM-DD format
 * @returns {Array} Array of { number, customerId, dueDate, daysOverdue, due } sorted by daysOverdue descending
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get VAT summary report.
 * @param {Array} invoices - Array of invoice objects
 * @returns {Array} Array of { rate, base, vat } sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    for (const line of invoice.lines) {
      const lineAmount = line.qty * line.unitPrice;
      const lineBase = roundCents(lineAmount * (1 - line.discountPercent / 100));
      const lineVat = roundCents(lineBase * line.vat);

      const rate = line.vat;
      if (!vatMap.has(rate)) {
        vatMap.set(rate, { rate, base: 0, vat: 0 });
      }
      const entry = vatMap.get(rate);
      entry.base += lineBase;
      entry.vat += lineVat;
    }
  }

  return Array.from(vatMap.values()).sort((a, b) => b.rate - a.rate);
}

